The expression $\mathrm{Mm}^+(L_d)$ and $\mathrm{Mm}^-(L_d)$ can be viewed as a component of a conjugate momentum: to a discrete four-point Lagrangian density $L_d$ consider the Lagrangian
	\begin{equation}\label{eq:LdDX}
	L_{d, \Delta x}(U^i,U^{i+1}) = \sum_j L_d(u^i_j,u^{i+1}_j,u^{i}_{j+1},u^{i+1}_{j+1}),
	\end{equation}
	where $U^i = (u^i_j)_j$. The discrete Lagrangian describes the temporal motion of the system via the discrete Euler--Lagrangian equation for ordinary differential equations
	\[
	0 = \nabla_{U^i} \left( L_{d, \Delta x}(U^{i-1},U^{i}) + L_{d, \Delta x}(U^i,U^{i+1}) \right).
	\]
	Associated discrete conjugate momenta are defined by $P_+^i = \nabla_{U^i}  L_{d, \Delta x}(U^{i-1},U^{i})$ and $P_-^i = - \nabla_{U^i} L_{d, \Delta x}(U^{i},U^{i+1})$. Indeed, the $j$th component is given as
	\begin{align*}
		(P_+^i)_j &= \nabla_2 L_d(u^{i-1}_j,u^{i}_j,u^{i-1}_{j+1},u^{i}_{j+1})  + \nabla_4 L_d(u^{i-1}_{j-1},u^{i}_{j-1},u^{i-1}_{j},u^{i}_{j})\\
		(P_-^i)_j &= -\nabla_1 L_d(u^i_j,u^{i+1}_j,u^{i}_{j+1},u^{i+1}_{j+1}) -\nabla_3 L_d(u^i_{j-1},u^{i+1}_{j-1},u^{i}_{j},u^{i+1}_{j}).
	\end{align*}

\label{prop:normaliseLd}
	Let $\mathfrak{u}_b = (u,u^+,u_+,u^-,u^-_+,u_-,u_-^+) \in (\mathbb{R}^d)^9$ be a stencil and $\mathring{L_d}$ be a discrete four-point Lagrangian.
	To any $c_b \in \mathbb{R}$, $p_b \in \mathbb{R}^d$ there exists an equivalent discrete Lagrangian $L_d$ with
	\begin{equation*}\label{eq:NormaliseLd}
		L_d(u,u^+,u_+,u^+_+) = c_b,
		\qquad
		\mathrm{Mm}^-(L_d)(\mathfrak{u}_b) = p_b.
	\end{equation*}
